 references=refs,
 source_formulation=dict(text='The seminar contrasts almost-linear incremental cycle detection with slower topological ordering and proposes a narrower combinatorial milestone. The user-approved researcher-list card instead retains the broader almost-linear ordering existence target with explicit comparisons and memory.',citation='primary',caption='Dagstuhl Seminar 25191, §4.17. The two time targets are not asserted equivalent.',format='editorial_paraphrase'),
